      externalId?: GeostoreExternalStationIdProto[];
      /** An identifier from a GELFS (Google EV Location Feed Specification) feed. */
      gelfsId?: GeostoreGelfsLocationIdProto[];
      /** An identifier from a OCPI (Open Charge Point Interface) feed, which uses the standard E-mobility ID format. */
